sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    try {

        var prompts = ["Business Rule", "Script Include function"];
        var setFields = ["script", "script_includes"];

        //(function(index) { ... })(i);

        for (var i = 0; i < prompts.length; i++) {
            (function(index) {

                var prompt = 'For servicenow write a script ' + prompts[index] + ' to ' + g_form.getValue('script_name').toString() + ". " +
                    'Please reply back only the script removing all explanations,comments, new line tags or anything which is not supported in servicenow syntax.';

                var getServerResponse = new GlideAjax('x_938076_now_utils.getGeminiResponse');
                getServerResponse.addParam('sysparm_name', 'geminiAutoGenerateScript');
                getServerResponse.addParam('sysparm_prompt', prompt);
                getServerResponse.getXMLAnswer(function(responseAnswer) {
                    g_form.addInfoMessage('Prompt ' + prompt);
                    var geminiAnswer = JSON.parse(responseAnswer);
                    g_form.setValue(setFields[index], geminiAnswer.answer);
                });

            })(i); // Pass the current index into the IIFE
        }


    } catch (ex) {
        g_form.addInfoMessage('Error ' + ex);
    }




}
